function Multiply(mat1, mat2: array [,] of integer): array [,] of integer;
begin
  var m := mat1.GetLength(0);
  var n := mat2.GetLength(1);
  var p := mat1.GetLength(1);
  Result := new integer[m, n];

  for var i := 0 to m - 1 do
    for var j := 0 to n - 1 do
    begin
      var tmp := 0;
      for var k := 0 to p - 1 do
        tmp += mat1[i, k] * mat2[k, j];
      Result[i, j] := tmp;
    end;
end;

function UnionArray(nums1, nums2: List<integer>): List<integer>;
begin
  nums1.RemoveAll(x -> x = 0);
  nums2.RemoveAll(x -> x = 0);

  var i := 0;
  var j := 0;

  while (i < nums1.Count) and (j < nums2.Count) do
  begin
    if nums1[i] <= nums2[j] then
      i += 1
    else
    begin
      nums1.Insert(i, nums2[j]);
      i += 1;
      j += 1;
    end;
  end;

  if j < nums2.Count then
    nums1.AddRange(nums2.Skip(j));

  Result := nums1;
end;

function MaxFreq(nums: array of integer; k: integer): integer;
begin
  &Array.Sort(nums);
  var left := 0;
  var right := 0;
  var maxFreq := 0;
  var total := 0;

  while right < nums.Length do
  begin
    total += nums[right];
    if nums[right] * (right - left + 1) <= total + k then
      maxFreq := Max(maxFreq, right - left + 1)
    else
    begin
      total -= nums[left];
      left += 1;
    end;
    right += 1;
  end;

  Result := maxFreq;
end;

