function FindLongestZeros(number: integer): integer;
begin
  var binaryStr := Convert.ToString(number, 2);
  var maxGap := 0;
  var currentGap := 0;

  foreach var bit in binaryStr do
  begin
    if bit = '0' then
      currentGap += 1
    else if bit = '1' then
    begin
      if currentGap > maxGap then
        maxGap := currentGap;
      currentGap := 0;
    end;
  end;

  Result := maxGap;
end;

function Factorial(n: integer): integer;
begin
  Result := 1;
  for var i := 2 to n do
    Result *= i;
end;

function SumOfDigitFactorials(n: integer): integer;
begin
  Result := 0;
  foreach var digitChar in n.ToString() do
  begin
    var digit := StrToInt(digitChar);
    Result += Factorial(digit);
  end;
end;

function MostFrequentNumbers(numbers: array of integer): array of integer;
begin
  var freqDict := new Dictionary<integer, integer>();
  foreach var num in numbers do
  begin
    if freqDict.ContainsKey(num) then
      freqDict[num] += 1
    else
      freqDict[num] := 1;
  end;

  var maxCount := freqDict.Values.Max();
  Result := freqDict.Where(x -> x.Value = maxCount).Select(x -> x.Key).ToArray();
end;

function IsPerfect(n: integer): boolean;
begin
  if n = 1 then
  begin
    Result := False;
    exit;
  end;

  var sum := 1;
  var i := 2;
  while i <= n / i do
  begin
    if n mod i = 0 then
      sum += i + (n div i);
    i += 1;
  end;

  if i * i = n then
    sum -= i;

  Result := sum = n;
end;

function FindPerfectNumbers(startVal, endVal: integer): array of integer;
begin
  var perfectNumbers := new List<integer>();

  for var num := startVal to endVal do
    if IsPerfect(num) then
      perfectNumbers.Add(num);

  Result := perfectNumbers.ToArray();
end;

function CountSetBits(n: integer): integer;
begin
  var count := 0;
  var temp := n;
  while temp > 0 do
  begin
    count += temp and 1;
    temp := temp shr 1;
  end;
  Result := count;
end;

function LengthLongestSubstring(s: string): integer;
begin
  var charMap := new Dictionary<char, integer>();
  var left := 0;
  var maxLength := 0;

  for var right := 0 to s.Length - 1 do
  begin
    var currentChar := s[right + 1];
    if charMap.ContainsKey(currentChar) then
      left := Max(left, charMap[currentChar] + 1);

    charMap[currentChar] := right;
    maxLength := Max(maxLength, right - left + 1);
  end;

  Result := maxLength;
end;

function SecondLargestDigit(s: string): integer;
begin
  var digits := new List<integer>();
  foreach var c in s do
    if c.IsDigit() then
      digits.Add(StrToInt(c));

  var uniqueDigits := digits.Distinct().Order().ToArray();
  if uniqueDigits.Length < 2 then
    Result := -1
  else
    Result := uniqueDigits[uniqueDigits.Length - 2];
end;

function FindCombinations(nums: array of integer; k: integer): List<array of integer>;
begin
  if nums.Length < k then
  begin
    Result := new List<array of integer>();
    exit;
  end;

  if nums.Length = k then
  begin
    Result := new List<array of integer>();
    Result.Add(nums);
    exit;
  end;

  if k = 1 then
  begin
    Result := new List<array of integer>();
    foreach var x in nums do
      Result.Add(|x|);
    exit;
  end;

  Result := new List<array of integer>();
  for var i := 0 to nums.Length - 1 do
  begin
    var remaining := nums.Skip(i + 1).ToArray();
    var subsets := FindCombinations(remaining, k - 1);
    foreach var subset in subsets do
    begin
      var newComb := new integer[subset.Length + 1];
      newComb[0] := nums[i];
      for var j := 0 to subset.Length - 1 do
        newComb[j + 1] := subset[j];
      Result.Add(newComb);
    end;
  end;
end;

function DpCountPattern(i, j: integer; text, pattern: string; lenText, lenPattern: integer): integer;
begin
  if j = lenPattern then
    Result := 1
  else if i = lenText then
    Result := 0
  else if text[i + 1] = pattern[j + 1] then
    Result := DpCountPattern(i + 1, j + 1, text, pattern, lenText, lenPattern) + DpCountPattern(i + 1, j, text, pattern, lenText, lenPattern)
  else
    Result := DpCountPattern(i + 1, j, text, pattern, lenText, lenPattern);
end;

function CountPatternAsSubsequence(text, pattern: string): integer;
begin
  var lenText := text.Length;
  var lenPattern := pattern.Length;
  Result := DpCountPattern(0, 0, text, pattern, lenText, lenPattern);
end;

